namespace b=b1071_test;
inline void need(bool v,const char*s){if(!v)throw std::domain_error(s);}
inline constexpr unsigned char surface_table[]{0xd0u,0x13u,0x41u,0x0u,0xa0u,0x7u,0x76u,0x0u,0x40u,0x8u,0x76u,0x0u,0xa0u,0x9u,0x76u,0x0u,0x0u,0xfdu,0x75u,0x0u,0xd0u,0xfcu,0x75u,0x0u,0x60u,0x7u,0x76u,0x0u,0xf0u,0xffu,0x75u,0x0u,0x0u,0x0u,0x76u,0x0u,0x60u,0xfbu,0x75u,0x0u,0x10u,0xfbu,0x75u,0x0u,0xc0u,0xf2u,0x75u,0x0u,0x90u,0xf2u,0x75u,0x0u,0x0u,0xf8u,0x75u,0x0u,0x10u,0xf8u,0x75u,0x0u,0x20u,0xf8u,0x75u,0x0u,0x30u,0xf8u,0x75u,0x0u,0x40u,0xf8u,0x75u,0x0u,0x70u,0xf5u,0x75u,0x0u,0xe0u,0xf7u,0x75u,0x0u,0xf0u,0xf7u,0x75u,0x0u,0x70u,0xfau,0x75u,0x0u,0x40u,0xfau,0x75u,0x0u,0x70u,0x13u,0x41u,0x0u,0xf0u,0x12u,0x41u,0x0u,0x70u,0x12u,0x41u,0x0u,0x80u,0x12u,0x41u,0x0u,0x0u,0x13u,0x41u,0x0u,0xb0u,0x13u,0x41u,0x0u,0xc0u,0x13u,0x41u,0x0u,0x90u,0x12u,0x41u,0x0u,0xc0u,0x12u,0x41u,0x0u};
inline constexpr unsigned char base_table[]{0x20u,0x13u,0x41u,0x0u,0xa0u,0x7u,0x76u,0x0u,0x40u,0x8u,0x76u,0x0u,0xa0u,0x9u,0x76u,0x0u};
inline void check_literals(const b::Memory&m){for(unsigned k=0;k<128u;++k)need(m.r8(0x785ef8u+k)==surface_table[k],"1071 complete original surface vtable");for(unsigned k=0;k<16u;++k)need(m.r8(0x785f8cu+k)==base_table[k],"1071 complete original basevtable fragment");}
struct Proof{std::array<unsigned,2>address{},size{};unsigned token(unsigned value,unsigned id,unsigned off=0u)const{need(id<2u&&off<size[id]&&value==address[id]+off,"1071 exact LIVE ordinal/offset raw relation");return 0xd0710000u+id*0x10000u+off;}unsigned end(unsigned value,unsigned bytes)const{need(bytes>0u&&bytes<=size[1]&&value==address[1]+bytes,"1071 exact one-past logical-pixel-end from complete LIVE extent");return 0xd0720000u+bytes;}};
struct World{
 unsigned root,base;b::Case c;static constexpr unsigned arena_size=65536u;
 World(unsigned r,unsigned a,b::Case v):root(r),base(a),c(v){}
 unsigned receiver()const{return base+0x400u;}unsigned requested()const{return 2u*c.width*c.height;}unsigned rounded()const{return(requested()+15u)&~15u;}unsigned color()const{return root==0x10a60u?0x7fu:0xffffu;}
 std::vector<unsigned>allocation_sizes()const{return{32u,rounded()};}unsigned fixture_count()const{return 0u;}std::vector<unsigned>free_order()const{return{};}
 void setup(b::Memory&m,unsigned char*arena,b::HeapAdapter&h)const{need((root==0x10a60u||root==0x3614c0u)&&h.addresses.empty()&&c.width>=4u&&c.width<=31u&&c.height>=4u&&c.height<=23u,"1071 valid constructor receiver/dimensions/no inputheap");check_literals(m);for(unsigned k=0;k<arena_size;++k)arena[k]=static_cast<unsigned char>(b::mix(c.seed+131u*k));}
 b::Inputs input()const{b::Inputs i{};i.ax=b::mix(c.seed+1u);i.cx=receiver();i.dx=b::mix(c.seed+2u);for(unsigned k=0;k<16u;++k)i.arg[k]=b::mix(c.seed+73u*k+17u);i.arg[0]=c.x;i.arg[1]=c.y;i.arg[2]=c.width;i.arg[3]=c.height;return i;}
 std::array<unsigned,16>caller()const{auto a=input().arg;a[0]=0u;a[1]=0u;return a;}ra2::platform::x87::Image expected_fp()const{return ra2::platform::x87::Image::empty(static_cast<std::uint16_t>(c.control));}
 Proof prove(const b::HeapAdapter&h)const{const auto live=h.live();const auto sizes=allocation_sizes();need(live.size()==2u&&h.addresses.size()==2u,"1071 two complete LIVE outputs");Proof p;for(unsigned id=0;id<2u;++id){const auto it=std::find_if(live.begin(),live.end(),[&](const auto&v){return v.ordinal==id;});need(it!=live.end()&&it->address==h.addresses[id]&&it->bytes==sizes[id],"1071 complete LIVE extent inventory before normalization");const auto relation=h.identify(it->address,it->bytes);need(relation.ordinal==id&&relation.offset==0u,"1071 immutable whole LIVE ordinal proof");p.address[id]=it->address;p.size[id]=it->bytes;}return p;}
 std::vector<unsigned char>block(unsigned id,const b::HeapAdapter&h)const{auto bytes=b::fresh(id,allocation_sizes().at(id));if(id==0u){const unsigned fields[]{0x785ef8u,c.width,c.height,0u,2u,h.addresses.at(1u),requested()};for(unsigned k=0;k<7u;++k)b::word(bytes,4u*k,fields[k]);bytes[28]=1u;}else{for(unsigned y=0;y<c.height;++y)for(unsigned x=0;x<c.width;++x){const auto pixel=2u*(y*c.width+x);bytes[pixel]=root==0x10a60u?127u:255u;bytes[pixel+1u]=root==0x10a60u?0u:255u;}}return bytes;}
 void expected_memory(std::vector<unsigned char>&a,const b::HeapAdapter&h)const{const unsigned fields[]{c.x,c.y,c.width,c.height,0u,h.addresses.at(0u),h.addresses.at(1u),h.addresses.at(1u)+requested(),requested(),0x8000u,c.width,c.height};for(unsigned k=0;k<12u;++k)b::word(a,receiver()-base+4u*k,fields[k]);}
 void normalize_before(std::vector<unsigned char>&,const b::HeapAdapter&)const{}
 unsigned normalize_arena(std::vector<unsigned char>&a,const Proof&p)const{auto k=receiver()-base;b::word(a,k+0x14u,p.token(b::readword(a,k+0x14u),0u));b::word(a,k+0x18u,p.token(b::readword(a,k+0x18u),1u));b::word(a,k+0x1cu,p.end(b::readword(a,k+0x1cu),requested()));return 3u;}
};
struct Observation{std::vector<b::Event>events;std::vector<std::vector<unsigned char>>live,prefree;std::vector<unsigned char>image,arena;unsigned scalar{},heap_bytes{},prefree_bytes{},normalizations{};};
inline Observation verify(const World&w,b::HeapAdapter&h,unsigned eax,const ra2::platform::x87::Image&fp,const std::vector<unsigned char>&bi,const std::vector<unsigned char>&ba,const unsigned char*image,const unsigned char*arena){need(h.addresses.size()==2u&&h.allocation_flags.size()==2u&&h.snapshots.empty()&&h.events().size()==2u&&h.live().size()==2u,"1071 exact2 targetallocations/no frees/no fixtureallocation");Observation o;o.events=h.events();const auto sizes=w.allocation_sizes();const auto proof=w.prove(h);for(unsigned id=0;id<2u;++id){const auto&e=o.events[id];need(e.kind==b::Event::Kind::allocate&&e.ordinal==id&&e.address==proof.address[id]&&e.result==e.address&&e.size==sizes[id]&&h.allocation_flags[id]==0u,"1071 real allocation order/fullrawresult/roundedbytes/flags");o.heap_bytes+=sizes[id];}
 auto expected=ba;w.expected_memory(expected,h);need(std::equal(bi.begin(),bi.end(),image)&&std::equal(expected.begin(),expected.end(),arena),"1071 independent whole image/64Karena receiver48bytes/padding");o.image=bi;o.arena=expected;o.normalizations=w.normalize_arena(o.arena,proof);
 for(unsigned id=0;id<2u;++id){const auto p=proof.address[id];auto bytes=std::vector<unsigned char>(reinterpret_cast<const unsigned char*>(std::uintptr_t(p)),reinterpret_cast<const unsigned char*>(std::uintptr_t(p))+sizes[id]);need(bytes==w.block(id,h),"1071 independent fullrounded header/pixelgrid/tail/lock0/owned1 byte oracle");if(id==0u){b::word(bytes,20u,proof.token(b::readword(bytes,20u),1u));++o.normalizations;}o.live.push_back(std::move(bytes));}
 need(eax==w.receiver(),"1071 full raw EAX receiver");o.scalar=eax;need(ra2::platform::x87::same_numeric(fp,w.expected_fp()),"1071 complete unchanged numeric x87 oracle");return o;}
inline void compare(const Observation&a,const Observation&d){need(a.scalar==d.scalar&&a.image==d.image&&a.arena==d.arena&&a.live==d.live&&a.events.size()==d.events.size(),"1071 paired fullEAX allheader/pixels/roundedtail/image/arena bytes");for(unsigned id=0;id<2u;++id){const auto&x=a.events[id],&y=d.events[id];need(x.kind==y.kind&&x.ordinal==y.ordinal&&x.size==y.size,"1071 paired two genuine allocation events");}}
inline void cleanup(b::HeapAdapter&h){if(h.live().empty())return;need(h.live().size()==2u,"1071 exact2 outputs before outsideobservation cleanup");for(unsigned id:{1u,0u})need(h.release(h.addresses[id])!=0u,"1071 real pixels-before-header cleanup after observations");need(h.live().empty(),"1071 no retained fixture allocations");}
